  // —— Landing · FAQ ——
  "landing.faq1.q": "How do I sign up?",
  "landing.faq1.a":
    "You need an invite code. After signing up you immediately get yourname.doulor.cn, yourname@doulor.cn, DNS management, the temp share box and a profile card — no extra conditions.",
  "landing.faq2.q": "Why does a module say it isn't open to me?",
  "landing.faq2.a":
    "Direct-link storage, AI Gateway, tunnels and proxy nodes consume real resources (storage, API quota, bandwidth), so they use “contribute to unlock”: submit one resource and it unlocks automatically once approved. One contribution per module is enough.",
  "landing.faq3.q": "What counts as a contribution?",
  "landing.faq3.a":
    "An AI model channel (a working upstream API), a proxy subscription link, or a tunnel config.yml. The system checks connectivity and availability first and unlocks immediately on success; if it fails you get the specific reason.",
  "landing.faq4.q": "Which mail clients are supported?",
  "landing.faq4.a":
    "You can read your inbox in the browser, and forward mail to your usual address. Once AI Gateway is unlocked, its API key works with popular clients (ChatGPT-Next-Web, LobeChat, the OpenAI SDK, and more).",
  "landing.faq5.q": "How is my data protected?",
  "landing.faq5.a":
    "All sensitive credentials (Cloudflare tokens, third-party keys) exist only in Worker environment variables. The frontend never trusts identity fields, and permissions are always validated server-side. User input is escaped against XSS.",
  "landing.faq6.q": "What's the architecture?",
  "landing.faq6.a":
    "A purely static frontend with a Cloudflare Workers backend — data in D1, files in R2, mail via Cloudflare Email Routing. No servers of our own, accelerated worldwide at the edge.",
  "landing.faq7.q": "Will more features be added?",
  "landing.faq7.a":
    "Yes. Domains, email, storage, AI, tunnels, proxy nodes, temp sharing and profile cards are covered today, and more will be added as needed.",

