    "“Everyone who votes wins” pays out immediately. “Designated option wins” lets you pick the single winning option below. “Majority / Minority wins” is computed from the counts. Ties mean every tied option wins.",
  "vote.adm.fixedOption": "Winning option (the designated one)",
  "vote.adm.fixedOptionPlaceholder": "Pick an option",
  "vote.adm.fixedOptionHint":
    "Only voters who picked this option win. It must be an option with a label. Users are NOT told which one it is before the draw (otherwise they would just pick it) — put it in the event body if you want it public.",
  "vote.adm.instantWarn":
    "⚠️ Side effect of instant settlement: the earlier you vote, the better your odds — the very first voter's option is the only one with votes (both the majority and the minority), so they always win. Choose “drawn after the deadline” for a fair race.",
  "vote.adm.instantFixedWarn":
    "⚠️ “Designated option + instant settlement” is easy to probe: a user can vote once from a throwaway account and see whether they won (a win shows as claimed) to reverse-engineer the answer. Choose “drawn after the deadline” to prevent that.",
  "vote.adm.drawHint":
    "An end time is required for automatic drawing (the scheduled task settles it). You can also press “Draw” in the list at any time.",
