  "dm.title": "Domains",
  "dn.terms.title": "Domain service statement & disclaimer",
  "dn.terms.intro":
    "We provide free subdomain registration, DNS resolution and related management. We will make reasonable efforts to keep registered domains available and will not privately deregister, delete or modify your domains (except for violation handling). However, we are not liable for network failures, upstream outages, unexpected incidents, or policy changes beyond our control. You must comply with the responsibilities below, otherwise this commitment is void.",
