  "dn.terms.forbidden.2": "Hosting phishing, malware, pornography, gambling or other illegal/abusive sites;",
  "dn.terms.forbidden.3": "Sending spam or conducting network attacks (e.g. DDoS);",
  "dn.terms.forbidden.4": "Abusing the API, registering maliciously, or attempting to bypass platform limits;",
  "dn.terms.forbidden.5": "Deploying high-risk services or content that may trigger third-party review/control;",
  "dn.terms.forbidden.6": "Impersonating governments, schools, official platforms, or infringing third-party trademarks/names;",
