  "st.ag.1.title": "1. Nature of the service",
  "st.ag.1.body":
    "This module only provides file storage and public direct-link sharing. The site does not guarantee permanent availability, non-deletion or data integrity — keep your own backups of anything important.",
  "st.ag.2.title": "2. Prohibited content",
  "st.ag.2.body":
    "Uploading, storing or sharing the following is strictly forbidden: (1) child sexual abuse material or any sexual content involving minors; (2) pornographic or obscene content (R18); (3) terrorism, extreme violence or gore; (4) pirated software, films, music, e-books or other copyright-infringing resources; (5) gambling, fraud, pyramid schemes and other illegal material; (6) malware, trojans, viruses or phishing pages; (7) content violating others' privacy or containing their sensitive personal data; (8) anything else violating the laws of your jurisdiction.",
  "st.ag.3.title": "3. Enforcement",
  "st.ag.3.body":
    "Upon discovery or verified report of the above, the site will immediately delete the files, disable your cloud drive, and — depending on severity — warn you, restrict features, or permanently ban the account without restoration. Where a crime is involved, the site will provide the necessary information to the competent authorities.",
  "st.ag.4.title": "4. Your responsibility",
  "st.ag.4.body":
    "You bear sole legal responsibility for everything you upload, store or share through this service and for all consequences thereof. If your content causes the site to face third-party claims, administrative penalties or other losses, you are obliged to compensate them.",
  "st.ag.5.title": "5. Direct links are public",
  "st.ag.5.body":
    "Direct links are public — anyone holding the link can open it. Never store private files, ID photos, keys or other sensitive information. You are responsible for what you share.",
  "st.ag.6.title": "6. Disclaimer & cooperation",
  "st.ag.6.body":
    "The site may, upon receiving a valid complaint or cooperating with an investigation, delete files and disable accounts without prior notice. Admins may adjust quotas, throttle speeds, or shut the whole feature down at any time.",
