  "px.probe.shortUnreachable": "Unreachable",
  "px.note":
    "The “XX ms” figure is the TCP handshake time from this site's server to the node address (to tell dead nodes from slow ones) — it is not a client-side speed test and the traffic doesn't pass through the node, so treat it as a reference only; your client's own latency test is authoritative. QUIC/UDP nodes (hysteria2 / tuic) can't be measured server-side. “Unreachable” only means this server can't connect, not that the node is down. Traffic and expiry come straight from the subscription source.",
  "px.ag.1.title": "1. Nature of the service",
  "px.ag.1.body":
    "This module only lets you browse and copy proxy subscription links. The nodes themselves are maintained by the admin; the site doesn't guarantee availability, speed or stability.",
  "px.ag.2.title": "2. Traffic & expiry info",
  "px.ag.2.body":
    "Remaining traffic, expiry dates and similar come straight from the subscription source; when they can't be parsed it shows Unknown.",
  "px.ag.3.title": "3. Usage restrictions",
  "px.ag.3.body":
    "Subscription links are for your own use only — no gifting, resale or public sharing. You are responsible for everything done through the nodes and must follow local laws and platform rules.",
  "px.ag.4.title": "4. Privacy",
  "px.ag.4.body":
    "Enabling this feature never uploads your proxy traffic to this site. When fetching a subscription the server proxies the request, so the source may log that access.",
  "px.ag.5.title": "5. Disclaimer",
  "px.ag.5.body":
    "The site bears no responsibility for any direct or indirect loss from using proxy nodes. The admin may disable individual nodes or the whole feature at any time.",
