  "dns.desc": "A single view of every DNS record on the platform, plus tools to manage any user's subdomains on their behalf (create, rename, delete, transfer). Records are written straight to Cloudflare with no review step; here you can see them all, spot what the rule engine flags, and edit or delete directly.",
