  /** Modules a first-donation reward code may redeem (2026-10-04) */
  "adm.firstDonation.title": "Modules redeemable with a first-donation code",
  "adm.firstDonation.desc":
    "A user's first approved donation automatically grants a pick-your-own permission code. Only the modules checked here can be redeemed with it. All modules are allowed by default.",
