  "adm.461": "Admin credentials (system access token)",
  "adm.462": "Every time you generate or regenerate the system access token in NewAPI, the old value is overwritten and stops working,",
  "adm.463": "which makes every admin-level call from this site (creating accounts, looking them up, setting quota, health checks) fail with an invalid-token error.",
  "adm.464": "Paste the new token here to recover — no redeploy needed.",
