  "adm.767": "Publishing",
  "adm.768": "Publish now",
  "adm.769": "Publish on a schedule",
  "adm.770": "Save as draft (invisible to users)",
  "adm.771": "Publish time",
  "adm.772": "It's published and pushed automatically at that time; if you asked for an email broadcast it's sent then too.",
  "adm.773": "Pop-up reminder",
  "adm.774": "No pop-up (overview only)",
  "adm.775": "Pop up once",
  "adm.776": "Pop up every visit (with “don't show again”)",
  "adm.777": "Pops up for signed-in users. After a user dismisses it, “once” never returns, while “every visit” lets them choose “don't show again”.",
  "adm.778": "Push to user email",
  "adm.779": "When ticked, publishing or saving sends this announcement to every verified user's email.",
  "adm.780": "Cancel",
  "adm.781": "Setting the status to “live” pushes it to messages immediately; “scheduled” puts it live at that time. When a user clicks “Join now”, server-side checks and automatic payout kick in.",
  "adm.782": "Title",
  "adm.783": "Body (Markdown supported)",
  "adm.784": "Status",
  "adm.785": "Reward label (for display)",
  "adm.786": "Go-live time",
  "adm.787": "It goes live and is pushed to messages at that time. Use a future time.",
  "adm.788": "Reward type",
  "adm.789": "A lottery's reward is always points (the pool is set in the winners section), so this is locked.",
  "adm.790": "Random amount within a range",
  "adm.791": "When on, a random whole number between the lower and upper bound is picked (everyone gets a different amount, like a lottery). The lower bound may be negative (deducts points).",
  "adm.792": "Minimum points",
  "adm.793": "Maximum points",
  "adm.794": "If the user hasn't bound a gateway account the payout can't be automatic and lands in “awaiting manual issue”, where you can handle it from the claim list.",
  "adm.795": "Configure it on the built-in first row of the “Points → Shop” product table; nothing is hard-coded here.",
  "adm.796": "Unlike wallet credit, points don't require the user to have bound a gateway account — they can save them up and later",
  "adm.797": "redeem them for gateway balance or buy shop items on the “Points & Shop” page themselves.",
  "adm.798": "A range-random amount is fixed per “event + user”: the same person retrying gets the same number,",
  "adm.799": "so refreshing never changes it. The amount actually paid out is recorded in the claim list.",
  "adm.800": "Entry type",
  "adm.801": "The user must enter this code on the event card to claim (case-insensitive). Publishing the code",
  "adm.802": "somewhere off-site like a QQ group notice proves they really joined. The code itself is never shown to users.",
  "adm.803": "Users enter their GitHub username and the server verifies it against this repository's stargazers list.",
  "adm.804": "It must be a public repository",
  "adm.805": "— the list can't be read from a private one, which would make verification fail for everyone.",
  "adm.806": "Claiming right after starring works (results are cached on demand; “not found” is only cached for a minute",
  "adm.807": "so someone who stars and immediately claims doesn't get a stale answer).",
  "adm.808": "The Worker also needs a GitHub token",
  "adm.809": "GitHub now requires authentication to return the stargazer list; without it users see “can't verify”.",
  "adm.810": "Number of winners",
  "adm.811": "Points pool (total)",
  "adm.812": "Distribution",
  "adm.813": "Split evenly (everyone gets the same)",
  "adm.814": "Split randomly (amounts differ, total unchanged)",
  "adm.815": "Clicking “Join the draw” only enters the lottery — nothing is paid out then. There are two ways to draw:",
  "adm.816": "click “Draw” in the event list to draw immediately, or let the “end time” above pass and it draws itself",
  "adm.817": "(with no end time it waits for you). At draw time winners are picked at random from the entrants,",
  "adm.818": "and the pool is split by the chosen method — evenly, or randomly with differing amounts but the same total.",
  "adm.819": "If fewer people entered than there are winners, everyone who entered wins.",
  "adm.820": "The pool can't be smaller than the number of winners (each needs at least 1 point).",
  "adm.821": "Cancel",
  "adm.822": "Records where the automatic payout failed can be marked as issued by hand here.",
