  "ap.reject": "Reject",
  "ap.orders": "Orders",
  "ap.ordersDesc": "Points are deducted at checkout. For official items a “pending” order needs you to act and then mark it; user items work as escrow — points go to the seller only after they deliver and the buyer confirms, and you can force a settlement or cancel with a refund here. Rental orders show the rental period and expiry; on expiry the system revokes the access and returns the stock.",
