  "ap.donationTitle": "Donation reward points",
  "ap.donationDesc": "Points are issued automatically once a donation is approved (or a reverse-proxy account is bound). 0 = nothing for that type.",
  "ap.donationNoTiers": "Couldn't fetch the tier list — refresh and try again.",
  "ap.donationDailyLabel": "Daily issue cap per person",
  "ap.donationDailyHint": "How many times one person can earn donation points per day; 0 = unlimited",
  "ap.timesPerDayUnit": "×/day",
  "ap.issueTimesLabel": "Issue count: ",
  "ap.donationIssueNote": "One issue per newly approved donation — this is the channel through which users can earn points repeatedly. AI channels / SenseTime keys / tunnels / proxy nodes are counted per donation record (re-approving the same record doesn't pay twice, but donating a new resource does); reverse-proxy accounts are counted per new binding, naturally capped by “how many accounts can be bound”.",
  "ap.dailyCapLabel": "Daily cap: ",
  "ap.donationDailyCapNote": "This is the hard ceiling against farming — once someone hits this many issues in a day, further donations pay nothing (the donation is still approved and access still granted, just without points; it resets the next day). 0 = unlimited.",
  "ap.valueImpactLabel": "This value directly drives the payout volume: ",
  "ap.valueImpactNote": "users can convert points into AI Gateway balance at the configured rate, so think it through before raising it.",
  "ap.inviteDesc": "Two payouts go to the inviter: a fixed reward when the friend signs up, and a commission on the points that friend earns later.",
  "ap.inviteEnable": "Enable invite rewards",
  "ap.inviteOn": "On: every valid invite really issues points",
  "ap.inviteOff": "Off: invites pay nothing",
  "ap.perInvite": "Per invited friend",
  "ap.perInviteHint": "Paid once per invited person; 0 = nothing",
  "ap.commissionLabel": "Commission on friends' earnings",
  "ap.commissionHint": "The percentage you take from each batch of points a friend earns (donations / events); 0 = off",
  "ap.inviteDailyLabel": "Daily cap per person",
  "ap.inviteDailyHint": "How many points one person can earn through invites per day (reward + commission combined); 0 = unlimited",
  "ap.pointsPerDay": "points/day",
  "ap.consumedOnlyLabel": "Only count invites that really used a slot",
  "ap.consumedOnlyNote": "With this off, ordinary invite codes from an open-registration window also pay rewards — those codes can be reused endlessly, which amounts to free money for throwaway accounts. Strongly recommended to keep it on.",
  "ap.toMoneyLabel": "In money terms: ",
  "ap.toMoneyCurrent": "1 point is currently ¥{v}, so ",
  "ap.toMoneyPerInvite": "each invite is worth ¥",
  "ap.toMoneyNote": "This money really leaves through “Redeem gateway balance” (it's upstream AI cost), so estimate the expected invite volume before changing the numbers.",
  "ap.oneLevelLabel": "Commission is one level only: ",
  "ap.oneLevelNote": "only the direct inviter counts, and the invite reward itself pays no commission (otherwise A→B→C compounds and the points supply blows up exponentially). Points issued manually by admins and seller earnings from the user marketplace don't earn commission either.",
  "ap.antiAltLabel": "Against alt accounts: ",
  "ap.antiAltNote": "signing up needs nothing but an email. With no daily cap and the switch above turned off, self-registered alts become a way to farm points.",
  "ap.editRedeemTitle": "Edit · Redeem gateway balance",
  "ap.editRedeemDesc": "This is the built-in shop item: users enter a points amount and convert it into AI Gateway balance at the rate below.",
  "ap.redeemEnabledLabel": "Listed (redemption open)",
  "ap.redeemEnabledHint": "When off, users still see their balance and history but can't redeem — points already issued don't disappear.",
  "ap.rateLabel": "Rate (how many ¥ per 1 point?)",
  "ap.rateHint": "1 means 1 point = ¥1 and 10 means 1 point = ¥10; decimals (e.g. 0.5) are allowed.",
  "ap.redeemDailyLabel": "Daily redemption cap per person",
  "ap.redeemDailyHint": "Defaults to 5; 0 = unlimited. Redemption really calls the gateway to add quota, so keeping a cap is recommended.",
  "ap.autoConfirmLabel": "User marketplace: auto-confirm after (days)",
  "ap.autoConfirmHint": "After the seller marks it delivered, if the buyer still hasn't confirmed within this many days, points are automatically settled to the seller (default 7; 0 = off). Orders with an active after-sale are never auto-settled.",
  "ap.err.autoConfirmRange": "Auto-confirm days must be between 0 and 90 (0 = off)",
  "ap.editProduct": "Edit item",
