  "ap.rentalModeHint": "When on, the buyer pays once for a period that then expires automatically (renewals extend the remaining days); when off it's a one-time purchase kept forever.",
  "ap.rentalDaysHint": "The rental period starts when delivery takes effect (automatic = checkout succeeded; manual = you click mark as delivered), not at checkout — so waiting time doesn't eat into the buyer's period.",
